  OCMTrajectoryBlockT *UnPack(const ::flatbuffers::resolver_function_t *_resolver = nullptr) const;
  void UnPackTo(OCMTrajectoryBlockT *_o, const ::flatbuffers::resolver_function_t *_resolver = nullptr) const;
